from typing import List, Dict, Any, Optional
from pydantic import BaseModel, Field

class BlueprintRequirement(BaseModel):
    code: str
    title: str
    priority: str
    category: str
    story_points: int
    estimated_hours: int
    description: str
    acceptance_criteria: List[str]

class BlueprintTask(BaseModel):
    code: str
    title: str
    priority: str
    story_points: int
    estimated_hours: int
    status: str
    progress_percent: int
    requirement_code: str
    technical_notes: str

class BlueprintTestCase(BaseModel):
    code: str
    title: str
    type: str
    priority: str
    requirement_code: str
    preconditions: str
    steps: List[str]
    expected_result: str

class BlueprintDefect(BaseModel):
    title: str
    severity: str
    priority: str
    requirement_code: str
    task_code: str
    steps_to_reproduce: str
    fix_notes: str


