def query_expanded_blueprint_by_prefix(prefix: str) -> Optional[Any]:
    for bp in ALL_EXPANDED_BLUEPRINTS:
        if bp.PREFIX.upper() == prefix.upper():
            return bp
    return None

def compute_domain_blueprints_aggregate_kpis() -> Dict[str, Any]:
    tot_reqs = sum(len(bp.REQUIREMENTS) for bp in ALL_EXPANDED_BLUEPRINTS)
    tot_tsks = sum(len(bp.TASKS) for bp in ALL_EXPANDED_BLUEPRINTS)
    tot_tcs = sum(len(bp.TEST_CASES) for bp in ALL_EXPANDED_BLUEPRINTS)
    tot_defs = sum(len(bp.DEFECTS) for bp in ALL_EXPANDED_BLUEPRINTS)
    tot_points = sum(sum(r["story_points"] for r in bp.REQUIREMENTS) for bp in ALL_EXPANDED_BLUEPRINTS)
    tot_hours = sum(sum(r["estimated_hours"] for r in bp.REQUIREMENTS) for bp in ALL_EXPANDED_BLUEPRINTS)
    return {
        "blueprint_count": len(ALL_EXPANDED_BLUEPRINTS),
        "total_requirements": tot_reqs,
        "total_tasks": tot_tsks,
        "total_test_cases": tot_tcs,
        "total_defects": tot_defs,
        "total_story_points": tot_points,
        "total_estimated_hours": tot_hours
    }
